crm = attio(credentials: acme_main)
graph = kg(credentials: native_knowledge)

movement nightly_mirror(root: <crm>) {

  root-[c:companies]-> {
    write graph-[:company]-> { unique by (`domains`), name: c.`Name`, domains: c.`Domains` }
  }

  root-[d:deals]-> {
    write graph-[:deal]-> {
      unique by (`name`)
      name:    d.`Name`
      company: FIRST(d-[:Company]->.`Domains`)
    }
  }
}

