    () => {
      write team-[:message]-> {
        channel: "#dealflow"
        text:    "New deal from ${msg-[:sender]->.`name`}: ${company.`url`}"
      }
    },
    () => {
      write aff-[:organization]-> {
        unique by (`name`)
        name:      company.`name`
        attio_url: company.`url`
      }
    },
  ])
}

