export node Deal {
  name: <text>
  website: <text>
}

export function `Upsert Deal`(d: <Deal>) {
  recent = crm-[x:`List Entry — Deal Pipeline`]-> {
    org = ONLY(x-[:`Organization`]->)
    nm  = IF org == null THEN "" ELSE COALESCE(org.`Name`, "") END
    return { nm: nm }
  }
  hits = FILTER(recent, (r) => {
    nm = COALESCE(AT(r, "nm"), "")
    return CONTAINS(d.website, nm)
  })
  return "done"
}

