graph = kg(credentials: native_knowledge)

movement nightly_mirror(root: <crm>) {

  root-[c:companies]-> {
    write graph-[:companies]-> { unique by (`domains`), name: c.`Name`, domains: c.`Domains` }
  }

  root-[d:deals]-> {
    write graph-[:deals]-> {
      unique by (`name`)
      name:    d.`Name`
      company ?: ONLY(d-[:Company]->.`Domains`)
    }
  }
}

