node Files {
  name: <text>
  data: <file>
}

node Deal {
  name:   <text>
  amount: <number>
  node participants {
    name: <text>
  }
}

movement files_to_dropbox(f: <Files>) {
  write drive-[:files]-> {
    name: f.`name`
    data: f.`data`
  }
}

movement intake(msg: <inbox-[:message]->>) {
  d = node { name: "Series A", amount: 5000000, participants: node { name: "Acme Ventures" } }

  msg-[f:_resources]-> {
    files_to_dropbox(f: node { name: f.`filename`, data: f.`data` })
  }
}

