function total(xs: <number[]>, i: <number>): <{ sum: number, seen: number }> {
  if i >= COUNT(xs) {
    return { sum: 0, seen: i }
  }
  rest = total(xs, i + 1)
  return { sum: AT(xs, i) + rest.sum, seen: rest.seen }
}

